{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Viqualine, a quinoline-piperidine analogue, had absolute oral bioavailability of 80% in healthy subjects after a 25 mg tablet vs IV, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Bicifadine, a rigid aryl-azabicyclic amine, showed approximately 67% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Cibenzoline, a basic imidazoline drug, had absolute oral bioavailability of 83% in healthy volunteers, supporting high F for this basic heteroaromatic amine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rolipram, a small heterocyclic drug, had absolute bioavailability of 73 ± 25% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Alvimopan had low absolute bioavailability (~6%) in humans, but its polar phenol/zwitterionic character is not shared by the query; this is contradictory evidence with limited transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Fenoldopam showed poor oral bioavailability in humans, but this is attributed to catechol/polar groups and extensive first-pass metabolism, features absent in the query; contradictory but low transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, rigid, basic naphthyridine-piperidine with no acidic or catechol groups. Direct human absolute bioavailability data for structurally related basic amines (viqualine 80%, bicifadine 67%, cibenzoline 83%, rolipram 73%) support F >= 20%. The low-F analogues (alvimopan, fenoldopam) owe their poor bioavailability to polar phenol/catechol/zwitterionic features absent in the query. Physicochemical ionization is a concern but not sufficient to override the transferable high-F evidence.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule.",
    "All evidence analogues have low Morgan similarity (<0.23), limiting structural transferability.",
    "First-pass metabolism and transporter-mediated absorption/efflux for the query are unknown.",
    "High basicity and negative logD may reduce passive permeability; experimental permeability or human PK data would reduce uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

